//types of file selectors

//tag selector

let body=document.getElementsByTagName("h1");
console.log(body[1]);

//classes selector
let classes=document.getElementsByClassName("a");
console.log(classes[0]);

//id selector
let val=document.getElementById("val");
console.log(val);

//query selector
let aa= document.querySelector("#val");
console.log(aa);

//query selector all
let bb=document.querySelectorAll("h1")
console.log(bb);

//step 1
let node=document.getElementsByClassName("a");

//read operation
let text = node[0].innerHTML;
console.log(text);

//write operation
let text1=node[0].textContent;
console.log(text1);

let node1=document.querySelector("button");

let text2 = node1.textContent;
console.log(text2);

let text3= node1.innerHTML;
console.log(text3);

let btn=document.querySelector("button");
btn.textContent="Hello";



let sty=document.querySelectorAll("h1");
console.log(sty);

sty[0].style.color="red";
sty[1].style.color="blue";


let cls=document.getElementsByClassName("cnt");
console.log(cls);

cls[0].style.backgroundColor="orange";

//to remove a class
//sty[1].classList.remove("hiden");

//to add a class
//sty[1].classList.add("body");

//toggle class
sty[1].classList.toggle("hiden");
sty[1].classList.toggle("body");

//1 create tag
const v=document.createElement("h3");
//2. put content
v.textContent = "added from js";

//3.Where we have to put first node
const h3 = document.getElementsByClassName("cnt");

//4.
h3[0].appendChild(v);

